package module

import (
	"fmt"
	"sort"
	"strings"

	"github.com/truvity/asg/bootstrap"
)

// Paths on the instance.
const (
	// LibDir holds the generated runner and the step, check and watch files.
	LibDir = "/usr/local/lib/asg"
	// InServiceUnit is the oneshot unit that runs the steps and checks.
	InServiceUnit = "asg-in-service.service"

	// DefaultReadyTimeoutSeconds bounds a ready check that names no timeout.
	DefaultReadyTimeoutSeconds = 120
)

const lifecycleScript = `#!/bin/bash
# Generated by github.com/truvity/asg/module. Run by asg-in-service.service on
# every boot: in the warm pool it does nothing; on a boot into service it runs
# in-service.d, then the ready.d checks. Any failure exits non-zero, so the
# bootstrap-ready service abandons the launch instead of completing it.
set -euo pipefail

LIB="${ASG_LIB:-/usr/local/lib/asg}"

log() { printf '%s asg-in-service: %s\n' "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" "$*" >&2; }

imds() {
  local t
  t="$(curl -fsS --connect-timeout 5 -X PUT -H 'X-aws-ec2-metadata-token-ttl-seconds: 300' http://169.254.169.254/latest/api/token)" || return 1
  curl -fsS --connect-timeout 5 -H "X-aws-ec2-metadata-token: $t" "http://169.254.169.254/latest/meta-data/$1"
}

# An empty answer (no such path) means the instance is not in a group at all,
# which a cold start under test is: treat it as going in service.
state="$(imds autoscaling/target-lifecycle-state 2>/dev/null || true)"
case "$state" in
  Warmed:*)
    log "target lifecycle state '$state': parked, nothing to start"
    exit 0
    ;;
  InService | "") ;;
  *)
    log "target lifecycle state '$state': nothing to do"
    exit 0
    ;;
esac

for f in "$LIB"/in-service.d/*; do
  [ -e "$f" ] || continue
  log "step $(basename "$f")"
  bash -e "$f"
done

for f in "$LIB"/ready.d/*; do
  [ -e "$f" ] || continue
  limit="$(sed -n 's/^# asg-timeout=//p' "$f" | head -n 1)"
  deadline=$((SECONDS + ${limit:-120}))
  until bash "$f" >/dev/null 2>&1; do
    if [ "$SECONDS" -ge "$deadline" ]; then
      log "ready check $(basename "$f") did not pass in time"
      exit 1
    fi
    sleep 2
  done
  log "ready check $(basename "$f") passed"
done
`

const inServiceUnitText = `[Unit]
Description=Start this instance's services when it goes in service
After=network-online.target bootstrap-secrets.service
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
TimeoutStartSec=900
ExecStart=/usr/local/lib/asg/lifecycle.sh

[Install]
WantedBy=multi-user.target
`

// numbered returns the file path of the i-th entry of dir.
func numbered(dir string, i int, name string) string {
	return fmt.Sprintf("%s/%s/%02d-%s.sh", LibDir, dir, i, name)
}

func scriptFile(path, header, script string) bootstrap.File {
	return bootstrap.File{
		Path: path, Mode: "0755", Delivery: bootstrap.DeliveryInline,
		Content: "#!/bin/bash\n" + header + strings.TrimRight(script, "\n") + "\n",
	}
}

// runnerFragment writes the runner, the unit and the step and check files.
func (c Contribution) runnerFragment() bootstrap.Fragment {
	items := []bootstrap.Item{
		bootstrap.File{Path: LibDir + "/lifecycle.sh", Mode: "0755", Delivery: bootstrap.DeliveryInline, Content: lifecycleScript},
		bootstrap.Unit{Name: InServiceUnit, Content: inServiceUnitText, Enable: true},
	}

	for i, s := range sortedSteps(c.InService) {
		items = append(items, scriptFile(numbered("in-service.d", i, s.Name), "# in-service step: "+s.Name+"\n", s.Script))
	}

	for i, r := range c.ReadyChecks {
		timeout := r.TimeoutSeconds
		if timeout == 0 {
			timeout = DefaultReadyTimeoutSeconds
		}

		items = append(items, scriptFile(numbered("ready.d", i, r.Name), fmt.Sprintf("# asg-timeout=%d\n# ready check: %s\n", timeout, r.Name), r.Script))
	}

	return bootstrap.Compose("asg lifecycle", items...)
}

// watchFragment writes the watchdog's check files.
func (c Contribution) watchFragment() bootstrap.Fragment {
	var items []bootstrap.Item

	for i, w := range c.Watch {
		items = append(items, scriptFile(numbered("watch.d", i, w.Name), "# watch check: "+w.Name+"\n", w.Script))
	}

	return bootstrap.Compose("asg watch checks", items...)
}

// SortedScrape returns the scrape targets by name, for a stable agent
// configuration.
func (c Contribution) SortedScrape() []ScrapeTarget {
	out := append([]ScrapeTarget(nil), c.Scrape...)
	sort.SliceStable(out, func(a, b int) bool { return out[a].Name < out[b].Name })

	return out
}

// ShellQuote quotes s for a POSIX shell.
func ShellQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }
